import { type InferSchemaType, type Model, model, models, Schema, type Types } from "mongoose";
import { Currency } from "sql";
import type {
	OrderFinancialDetails,
	OrderTransaction,
	RegionalCountry,
	TotalByCurrency,
} from "../types/order";

export const OrderSchema = new Schema(
	{
		billingAddressId: { required: true, type: String },
		cancelledAt: { type: Date },
		cartToken: { index: true, type: String },
		closedAt: { type: Date },
		confirmationNumber: { type: String },
		confirmed: { type: Boolean },
		contactEmail: { searchIndex: true, type: String },
		currency: { enum: Currency, required: true, type: String },
		customerAddressId: { required: true, type: String },
		customerId: { index: true, required: true, type: String },
		customerName: { required: true, searchIndex: true, type: String },
		description: { default: "", required: true, type: String },
		discountAllocations: { default: [], type: [Schema.Types.Mixed] },
		disputes: { type: Schema.Types.Mixed },
		externalCreatedAt: { index: true, type: Date },
		externalCustomerId: { required: true, type: String },
		externalId: { required: true, type: String },
		externalNumber: { required: true, type: String },
		externalPlatformEntityTracking: { index: true, type: [String] },
		externalSequenceNumber: { type: Number },
		fulfillmentMeta: { type: [Schema.Types.Mixed] },
		integrationSetHasCheckoutId: { index: true, type: String },
		integrationSetHasGatewayId: { index: true, type: String },
		integrationSetHasVirtualStoreId: { index: true, required: true, type: String },
		lineItemsSubtotal: { default: [], type: [Schema.Types.Mixed] },
		manualOverrides: { required: false, type: Schema.Types.Mixed },
		paymentMethod: { index: true, required: true, type: String },
		paymentStatus: { index: true, required: true, type: String },
		phone: { type: String },
		presentmentMoney: { type: Schema.Types.Mixed },
		processedAt: { type: Date },
		productCost: {
			type: [
				{
					cost: { type: Schema.Types.Mixed },
					costId: { type: String },
					costOptionId: { type: String },
					costOptionItemId: { type: String },
					productQuantity: { type: Schema.Types.Mixed },
					products: { type: [String] },
					shipping: { type: Schema.Types.Mixed },
				},
			],
		},
		products: { ref: "Product", required: true, type: [Schema.Types.ObjectId] },
		recoverUrl: { type: String },
		regionalCountry: {
			type: {
				country: { required: true, type: String },
				state: { required: true, type: String },
			},
		},
		shippingTotal: { type: Schema.Types.Mixed },
		shopMoney: { required: true, type: Schema.Types.Mixed },
		srcPlatform: { type: String },
		token: { type: String },
		totalPrice: { type: Schema.Types.Mixed },
		trackingCode: { type: [String] },
		trackingCodeUrl: { type: [String] },
		transactions: { type: Schema.Types.Mixed },
		utm: { required: false, type: Schema.Types.Mixed },
		variants: { ref: "Variant", required: true, type: [Schema.Types.ObjectId] },
	},
	{ timestamps: true },
);

OrderSchema.index({
	_id: 1,
	externalCreatedAt: 1,
	integrationSetHasVirtualStoreId: 1,
	paymentStatus: 1,
});

OrderSchema.index({
	products: 1,
});

OrderSchema.index({
	integrationSetHasVirtualStoreId: 1,
	products: 1,
	externalCreatedAt: 1,
});

export type OrderDocument = Omit<
	InferSchemaType<typeof OrderSchema>,
	| "discountAllocations"
	| "disputes"
	| "lineItemsSubtotal"
	| "manualOverrides"
	| "presentmentMoney"
	| "productCost"
	| "regionalCountry"
	| "shippingTotal"
	| "shopMoney"
	| "totalPrice"
	| "transactions"
	| "utm"
> & {
	lineItemsSubtotal: Array<{
		productId: Types.ObjectId | null;
		variantId: Types.ObjectId | null;
		shopMoney: {
			amount: number;
			currency: Currency;
		};
		presentmentMoney: {
			amount: number;
			currency: Currency;
		};
	}>;
	discountAllocations: Array<{
		productId: Types.ObjectId;
		variantId: Types.ObjectId;
		amount: number;
		currency: Currency;
		discountApplicationIndex: number;
		amount_set: {
			shop_money: {
				amount: number;
				currency_code: Currency;
			};
			presentment_money: {
				amount: number;
				currency_code: Currency;
			};
		};
	}>;
	presentmentMoney: OrderFinancialDetails;
	shopMoney: OrderFinancialDetails;
	shippingTotal: {
		shopMoney: {
			currency: Currency;
			amount: number;
		};
		presentmentMoney: {
			currency: Currency;
			amount: number;
		};
	};
	totalPrice: {
		shopMoney: {
			currency: Currency;
			amount: number;
		};
		presentmentMoney: {
			currency: Currency;
			amount: number;
		};
	};
	productCost: Array<{
		cost?: TotalByCurrency;
		costId: string | null;
		costOptionId: string | null;
		costOptionItemId: string | null;
		productQuantity: Record<string, number>;
		products: string[];
		shipping?: TotalByCurrency;
	}>;
	regionalCountry?: RegionalCountry;
	disputes?: OrderTransaction[];
	transactions?: OrderTransaction[];
	utm?: {
		source?: string;
		campaign?: string;
		medium?: string;
		term?: string;
		content?: string;
	};
	manualOverrides?: {
		revenue?: { currency: Currency; amount: number };
		paymentMethod?: string;
		shipping?: { currency: Currency; amount: number };
		taxes?: { currency: Currency; amount: number };
		fees?: { currency: Currency; amount: number };
		productCost?: { currency: Currency; amount: number };
	};
};

export const OrderModel =
	(models.Order as Model<OrderDocument> | undefined) || model<OrderDocument>("Order", OrderSchema);

