package entities

import "time"

type MoneyValue struct {
	Amount   float64 `json:"amount" bson:"amount"`
	Currency string  `json:"currency" bson:"currency"`
}

type MoneyPair struct {
	ShopMoney        MoneyValue `json:"shopMoney" bson:"shopMoney"`
	PresentmentMoney MoneyValue `json:"presentmentMoney" bson:"presentmentMoney"`
}

type OrderMoney struct {
	SubtotalValue  float64 `json:"subtotalValue" bson:"subtotalValue"`
	TotalValue     float64 `json:"totalValue" bson:"totalValue"`
	TotalDiscounts float64 `json:"totalDiscounts" bson:"totalDiscounts"`
	TotalTax       float64 `json:"totalTax" bson:"totalTax"`
	Currency       string  `json:"currency" bson:"currency"`
}

type RegionalCountry struct {
	Country string `json:"country" bson:"country"`
	State   string `json:"state" bson:"state"`
}

type UTMData struct {
	Source   string `json:"source" bson:"source"`
	Campaign string `json:"campaign" bson:"campaign"`
}

type DiscountValue struct {
	ShopMoney        MoneyValue `json:"shopMoney" bson:"shopMoney"`
	PresentmentMoney MoneyValue `json:"presentmentMoney" bson:"presentmentMoney"`
}

// LineItemSubtotal represents a line item subtotal.
// ProductID / VariantID hold the raw platform externalId on the write path
// (populated by normalizers) and are resolved to the matching product/variant
// ObjectID at storage time via a batch lookup (`storage/order/order_mongo.go`).
// On the read path, the repository populates them with the stored ObjectID hex
// string so API consumers keep seeing a stable reference identifier.
type LineItemSubtotal struct {
	ProductID        string          `json:"productId" bson:"productId"`
	VariantID        string          `json:"variantId" bson:"variantId"`
	ShopMoney        MoneyValue      `json:"shopMoney" bson:"shopMoney"`
	PresentmentMoney MoneyValue      `json:"presentmentMoney" bson:"presentmentMoney"`
	Discounts        []DiscountValue `json:"discounts" bson:"discounts"`
}

type TransactionFeeType string

const (
	TransactionFeeTypeProcessing TransactionFeeType = "PROCESSING"
	TransactionFeeTypeExchange   TransactionFeeType = "EXCHANGE"
	TransactionFeeTypeUnknown    TransactionFeeType = "UNKNOWN"
)

type TransactionFee struct {
	ExternalID string             `json:"externalId" bson:"externalId"`
	Type       TransactionFeeType `json:"type" bson:"type"`
	Fixed      MoneyValue         `json:"fixed" bson:"fixed"`
	Variable   MoneyValue         `json:"variable" bson:"variable"`
}

// EmbeddedTransaction represents a transaction embedded inside an Order document.
// This matches the old go-worker format where transactions are arrays inside orders.
type EmbeddedTransaction struct {
	ExternalID       string            `json:"externalId" bson:"externalId"`
	Amount           float64           `json:"amount" bson:"amount"`
	Currency         string            `json:"currency" bson:"currency"`
	Fees             []TransactionFee  `json:"fees" bson:"fees"`
	Type             string            `json:"type" bson:"type"`
	Status           string            `json:"status" bson:"status"`
	ProcessedAt      *time.Time        `json:"processedAt" bson:"processedAt"`
	OrderDescription string            `json:"orderDescription" bson:"orderDescription"`
}

// EmbeddedDispute represents a dispute embedded inside an Order document.
type EmbeddedDispute struct {
	ExternalID       string            `json:"externalId" bson:"externalId"`
	Amount           float64           `json:"amount" bson:"amount"`
	Currency         string            `json:"currency" bson:"currency"`
	Fees             []TransactionFee  `json:"fees" bson:"fees"`
	Type             string            `json:"type" bson:"type"`
	Status           string            `json:"status" bson:"status"`
	ProcessedAt      *time.Time        `json:"processedAt" bson:"processedAt"`
	OrderDescription string            `json:"orderDescription" bson:"orderDescription"`
}

// IsFeeOnly returns true if this is a fee-only update (no full dispute data).
func (d *EmbeddedDispute) IsFeeOnly() bool {
	return d.ExternalID == ""
}

import {
