const BRAZIL_UTC_DIFFERENCE = 3;

@TraceClass()
export class YampiWebhookMapper extends CheckoutWebhookMapper {
	constructor(private productRepository: ProductsRepository) {
		super();
	}

	mapCustomer(customer: Customer): OrderUpdatedEventCustomer | AbandonedCartEventCustomer {
		return {
			email: customer.data.email,
			externalId: String(customer.data.id),
			firstName: customer.data.first_name,
			fullName: customer.data.generic_name,
			lastName: customer.data.last_name,
			legalId: customer.data.cpf ?? customer.data.cnpj,
			phoneNumber: customer.data.phone.whatsapp_link.split("=")[1],
		};
	}

	mapAddress(address: Address): OrderUpdatedEventAddress {
		const { data } = address;
		const countryCode = data.country;
		const country = CountrySymbolMapper.convert(countryCode);
		const provinceCode = data.state;
		const stateSymbolMapper = new StateSymbolMapperFactory().get(countryCode);
		const province = stateSymbolMapper.convert(provinceCode);

		return {
			city: data.city,
			country,
			countryCode,
			description: data.full_address,
			externalId: String(data.id),
			province,
			provinceCode,
			zipCode: data.zipcode,
		};
	}

	mapPaymentMethod(payment: PaymentDetail): PaymentMethod {
		const paymentMethodMapping: Record<string, PaymentMethod> = {
			is_billet: PaymentMethod.BANK_SLIP,
			is_credit_card: PaymentMethod.CREDIT_CARD,
			is_deposit: PaymentMethod.DEBIT_CARD,
			is_pix: PaymentMethod.PIX,
		};
		for (const [key, method] of Object.entries(paymentMethodMapping)) {
			if (payment[key]) {
				return method;
			}
		}
		return PaymentMethod.UNKNOWN;
	}

	mapPaymentStatus(transaction: Transaction): PaymentStatus {
		const { status } = transaction;
		const paymentStatusMapping: Record<string, PaymentStatus> = {
			authorized: PaymentStatus.PENDING,
			cancelled: PaymentStatus.CANCELED,
			paid: PaymentStatus.PAID,
			refused: PaymentStatus.REFUSED,
			voided: PaymentStatus.CANCELED,
			waiting_payment: PaymentStatus.PENDING,
		};
		return paymentStatusMapping[status] ?? PaymentStatus.UNKNOWN;
	}

	async mapProducts(items: Items, allProducts: Product[]): Promise<AbandonedCartEventProduct[]> {
		const productNames = allProducts.map(product => product.name);
		const matchedProducts: AbandonedCartEventProduct[] = [];
		if (productNames.length) {
			await Promise.all(
				items.data.map(async item => {
					const { sku } = item;
					const { data } = sku;
					const { title, variations } = data;
					const productComparison = stringComparison.cosine.sortMatch(
						title,
						productNames,
					) as SortMatchResultType[];
					const mostSimilarProduct = productComparison.at(-1)!;
					const { index: productIndex } = mostSimilarProduct;
					const matchedProduct = allProducts[productIndex];
					const fullProduct = await this.productRepository.filterByExternalIds(
						[matchedProduct.externalId],
						true,
					);
					const firstProduct = fullProduct[0];
					const { variants } = firstProduct;
					const variantNames = variants.map(variant => variant.name);
					const yampiVariantNameArray = variations.map(variation => variation.value);
					const fullVariantName = yampiVariantNameArray.join(" / ");
					const variantComparison = stringComparison.cosine.sortMatch(
						fullVariantName,
						variantNames,
					) as SortMatchResultType[];
					const mostSimilarVariant = variantComparison.at(-1)!;
					const { index: variantIndex } = mostSimilarVariant;
					const matchedVariant = variants[variantIndex];
					matchedProducts.push({
						description: firstProduct.description,
						externalId: firstProduct.externalId,
						handle: firstProduct.handle,
						name: firstProduct.name,
						picture: firstProduct.picture?.src
							? firstProduct.picture
							: firstProduct.pictureUrl
								? { src: firstProduct.pictureUrl }
								: undefined,
						status: firstProduct.status,
						variant: {
							externalCreatedAt: matchedVariant.externalCreatedAt,
							externalId: matchedVariant.externalId,
							name: matchedVariant.name,
							picture: matchedVariant.picture?.src
								? matchedVariant.picture
								: matchedVariant.pictureUrl
									? { src: matchedVariant.pictureUrl }
									: undefined,
							sku: matchedVariant.sku,
							value: matchedVariant.value,
						},
					});
				}),
			);
		}
		return matchedProducts;
	}

	mapSourceVirtualStore(metadata: Metadata): Integrations {
		const valueRecord: Record<string, Integrations> = {
			shopify: Integrations.SHOPIFY,
		};
		const { data } = metadata;
		const srcPlatform: MetadataItem | undefined = data.find(metaData => metaData.key === "source_platform");
		const value = srcPlatform?.value || "";
		return valueRecord[value] ?? Integrations.YAMPI;
	}

	mapSequenceNumber(metadata: Metadata): string | undefined {
		const { data } = metadata;
		const sequenceNumber: MetadataItem | undefined = data.find(
			metaData => metaData.key === "platform_order_number",
		);
		return sequenceNumber?.value;
	}

	mapDateToUTC(date: Date): Date {
		const mappedDate = new Date(date);
		mappedDate.setHours(mappedDate.getHours() + BRAZIL_UTC_DIFFERENCE);
		return mappedDate;
	}
}

import { OrderUpdatedEvent, OrderUpdatedEventData } from "@modules/orders";
import { ProductsRepository } from "@modules/repositories/entities/products.repository";
import { SendWebhookDTO } from "@modules/webhooks/dto/SendWebhookDTO.dto";
import { Integrations, PaymentStatus, PlatformCategory } from "@shared/types";
import { generateUUID } from "@utils";
import { WebhookMapper } from "../../..";
import { YampiWebhookMapper } from "../YampiWebhookMapper";
import YampiOrderUpdatedWebhook, { Resource } from "./YampiOrderUpdatedWebhook";

interface MapEntityParams {
	body: YampiOrderUpdatedWebhook;
	integrationSetId: string;
	integrationSetHasCheckoutId: string;
	integrationSetHasVirtualStoreId: string;
}

export default class YampiOrderUpdatedWebhookMapper implements WebhookMapper {
	sharedMapper: YampiWebhookMapper;

	constructor(private productRepository: ProductsRepository) {
		this.sharedMapper = new YampiWebhookMapper(this.productRepository);
	}

	async execute({
		body,
		integrationSetId,
		integrationSetHasCheckoutId,
		integrationSetHasVirtualStoreId,
	}: SendWebhookDTO): Promise<OrderUpdatedEvent[]> {
		return this.mapPayload({
			body: body as YampiOrderUpdatedWebhook,
			integrationSetHasCheckoutId,
			integrationSetHasVirtualStoreId,
			integrationSetId,
		});
	}

	private async mapPayload({
		body,
		integrationSetId,
		integrationSetHasCheckoutId,
		integrationSetHasVirtualStoreId,
	}: MapEntityParams): Promise<OrderUpdatedEvent[]> {
		const resource = body.resource;

		const data = this.getOrderUpdatedData(
			resource,
			integrationSetId,
			integrationSetHasCheckoutId,
			integrationSetHasVirtualStoreId,
		);

		const events: OrderUpdatedEvent[] = [];

		const mainEvent = new OrderUpdatedEvent(data);

		const currentDate = new Date();
		const { pixExpiration } = mainEvent.data;

		events.push(mainEvent);

		if (
			mainEvent.data.paymentStatus === PaymentStatus.PENDING &&
			pixExpiration &&
			pixExpiration > currentDate
		) {
			const futureOrderUpdatedEvent = new OrderUpdatedEvent(
				{
					...mainEvent.data,
					paymentStatus: PaymentStatus.CANCELED,
				},
				{ when: mainEvent.data.pixExpiration },
			);
			events.push(futureOrderUpdatedEvent);
		}

		return events;
	}

	private getExternalId(resource: Resource): string {
		let externalId = String(resource.id);
		resource.services.data.forEach(service => {
			Object.keys(service).forEach(appName => {
				const appService = service[appName];
				if (appService.external_id) {
					externalId = appService.external_id;
				}
			});
		});

		return externalId;
	}

	getOrderUpdatedData(
		resource: Resource,
		integrationSetId: string,
		integrationSetHasVirtualStoreId: string,
		integrationSetHasCheckoutId?: string,
	) {
		const { transactions } = resource;
		const latestTransaction = transactions.data[0];
		const currency = this.sharedMapper.mapCurrency(latestTransaction.installment_formated);

		const { payment } = latestTransaction;
		const { data: paymentData } = payment;

		const externalId = this.getExternalId(resource);

		const srcVirtualStore = this.sharedMapper.mapSourceVirtualStore(resource.metadata);

		const pixExpiration = this.sharedMapper.mapDateToUTC(new Date(resource.pix.data.pix_expiration_date));

		const data: OrderUpdatedEventData = {
			billetCode: latestTransaction.billet_barcode ?? undefined,
			billetUrl: latestTransaction.billet_url ?? undefined,
			campaignPlatform: "",
			cartToken: resource.cart_token,
			currency,
			externalId,
			externalNumber: "",
			externalPlatformEntityTracking: [
				`${Integrations.YAMPI}|${resource.id}`,
				`${srcVirtualStore}|${externalId}`,
			],
			id: generateUUID(new Date().toISOString()),
			integrationSetHasCheckoutId,
			integrationSetHasVirtualStoreId,
			integrationSetId,
			lineItemsSubtotal: [],
			paymentMethod: this.sharedMapper.mapPaymentMethod(paymentData),
			paymentStatus: this.sharedMapper.mapPaymentStatus(latestTransaction),
			pixCode: resource.pix.data.pix_qr_code,
			pixExpiration,
			// In the future it might be a virtual-store aswell
			platformCategory: PlatformCategory.CHECKOUT,
			products: [],
			regionalCountry: {
				country: "unknown",
				state: "",
			},
			shopMoney: {
				currency,
				subtotalValue: resource.buyer_value_total,
				totalDiscounts: resource.value_discount,
				totalTax: resource.value_tax,
				totalValue: resource.value_total,
			},
			srcPlatform: srcVirtualStore,
		};

		return data;
	}
}
